import stylesText from './line-set-editor.css?inline';
import { cssStyleSheet } from '../../../../utils/css.js';
import { MEAL_TYPES, type MealType } from '@motivation/shared';
import { unitLabel, withAmount, type LineView } from '../../../../utils/line-view.js';
import { roundAmount } from '../../../../utils/amount-steps.js';
import { formatMacro } from '../../../../utils/format-macro.js';
import { showModalFresh } from '../../../../utils/dialog.js';
import {
    HEALTH_EVENTS,
    createLineSetDeleteEvent,
    createLineSetSaveEvent,
    type LineEditorSaveEvent,
    type LineOpenEvent,
    type LinesChangeEvent,
} from '../../health-events.js';
import { dispatchAndSettle, whileBusy } from '../../../../utils/in-flight.js';
import '../line-list/line-list.component.js';
import '../line-editor/line-editor.component.js';
import '../../photo-controls/photo-controls.component.js';
import type { LineList } from '../line-list/line-list.component.js';
import type { LineEditor } from '../line-editor/line-editor.component.js';
import type { PhotoControls } from '../../photo-controls/photo-controls.component.js';

const styles = cssStyleSheet(stylesText);

export const LINE_SET_MODES = ['meal', 'log-new', 'log', 'draft'] as const;
export type LineSetMode = typeof LINE_SET_MODES[number];

const SAVE_LABELS: Record<LineSetMode, string> = { meal: 'Save meal', 'log-new': 'Log', log: 'Save', draft: 'Log' };

const template = document.createElement('template');
template.innerHTML = `
    <section class="card head">
        <photo-controls scope="meal" class="cover" hidden></photo-controls>
        <label class="field name-field"><span class="label">Name</span><input class="name" autocomplete="off"></label>
        <label class="field notes-field" hidden><span class="label">Notes</span><textarea class="notes" rows="2"></textarea></label>
        <div class="context">
            <label class="field"><span class="label">Day</span><input class="date" type="date" required></label>
            <label class="field"><span class="label">Slot</span><select class="slot">
                ${MEAL_TYPES.map((m) => `<option value="${m}">${m}</option>`).join('')}
            </select></label>
            <label class="field"><span class="label">Eaten at</span><input class="time" type="time"></label>
        </div>
    </section>
    <section class="card lines">
        <line-list editable removable addable></line-list>
    </section>
    <label class="also-meal" hidden><input type="checkbox" class="also-meal-box"> <span class="also-meal-text">Also update the meal</span></label>
    <p class="error set-error" role="alert" hidden></p>
    <div class="actions">
        <button type="button" class="delete" hidden>Delete</button>
        <button type="button" class="save"></button>
    </div>
    <dialog class="sheet line-sheet" aria-label="Line">
        <div class="sheet-head">
            <span class="line-sheet-title"></span>
            <button type="button" class="sheet-close" aria-label="Close">×</button>
        </div>
        <p class="line-sheet-note" role="status" hidden></p>
        <line-editor removable></line-editor>
    </dialog>
`;

/**
 * Story 422 (418 Shape) — the editor of a list of lines, for a meal, a log being made, a log, or
 * an AI draft (`mode`). Name, and for the log modes the day, slot and eaten-at time, around an
 * editable `<line-list>` (± on every line, remove, add, portion). A log from a meal offers an
 * opt-in "also update the meal" (418 #8). It never writes: Save emits `health:line-set-save`,
 * Delete (`deletable`) `health:line-set-delete`, and "+ Add" `health:line-add-request` — the
 * screen picks a food and hands it to `addLine()`.
 */
export class LineSetEditor extends HTMLElement {
    static get observedAttributes() { return ['mode', 'deletable', 'meal-linked', 'name-required']; }

    private linesValue: LineView[] = [];
    /** Meal mode: the cover as picked, held until Save (story 403's pattern). */
    private imagePath: string | null = null;

    constructor() {
        super();
        const shadow = this.attachShadow({ mode: 'open' });
        shadow.adoptedStyleSheets = [styles];
        shadow.appendChild(template.content.cloneNode(true));
        customElements.upgrade(shadow);

        // Story 434: a line opens in a sheet over the list — the same detail in a log, a meal or a draft.
        this.list.addEventListener(HEALTH_EVENTS.LINE_OPEN, (e: LineOpenEvent) => {
            e.stopPropagation();
            this.openLine(e.detail.key);
        });
        const sheet = shadow.querySelector('.line-sheet') as HTMLDialogElement;
        sheet.querySelector('.sheet-close')!.addEventListener('click', () => sheet.close());
        const detail = sheet.querySelector('line-editor') as LineEditor;
        detail.addEventListener(HEALTH_EVENTS.LINE_EDITOR_SAVE, (e: LineEditorSaveEvent) => {
            e.stopPropagation();
            const { amount, override } = e.detail;
            this.replaceOpen((l) => {
                const { override: _old, ...rest } = withAmount(l, amount);
                return override ? { ...rest, override } : rest;
            });
            sheet.close();
        });
        detail.addEventListener(HEALTH_EVENTS.LINE_EDITOR_REMOVE, (e) => {
            e.stopPropagation();
            this.replaceOpen(() => null);
            sheet.close();
        });

        const cover = shadow.querySelector('photo-controls') as PhotoControls;
        cover.addEventListener(HEALTH_EVENTS.PHOTO_PICKED, (e) => { e.stopPropagation(); this.imagePath = e.detail.image_path; });
        cover.addEventListener(HEALTH_EVENTS.PHOTO_REMOVED, (e) => { e.stopPropagation(); this.imagePath = null; });
        cover.addEventListener(HEALTH_EVENTS.PHOTO_LANDED, (e) => { this.imagePath = e.detail.image_path; });

        this.list.addEventListener(HEALTH_EVENTS.LINES_CHANGE, (e: LinesChangeEvent) => {
            e.stopPropagation();
            this.linesValue = e.detail.lines;
            this.namePlaceholder();
        });
        // Story 371: each button stays disabled until the screen's write settles — a double tap writes once.
        const save = shadow.querySelector('.save') as HTMLButtonElement;
        save.addEventListener('click', () => void whileBusy(save, () => this.save()));
        const del = shadow.querySelector('.delete') as HTMLButtonElement;
        del.addEventListener('click', () => void whileBusy(del, () => dispatchAndSettle(this, createLineSetDeleteEvent())));
    }

    get mode(): LineSetMode {
        const m = this.getAttribute('mode');
        return (LINE_SET_MODES as readonly string[]).includes(m ?? '') ? m as LineSetMode : 'log';
    }

    get lines(): LineView[] { return this.linesValue; }
    set lines(value: LineView[]) {
        this.linesValue = value;
        this.list.lines = value;
        this.namePlaceholder();
    }

    /** Story 434: a log left unnamed is called after its first food — the field says so. */
    private namePlaceholder(): void {
        const name = this.shadowRoot!.querySelector('.name') as HTMLInputElement;
        name.placeholder = this.mode === 'meal' ? '' : (this.linesValue[0]?.name ?? '');
    }

    /**
     * Set the head fields at once; `time` is HH:MM or '' for unstamped. Meal mode takes the notes
     * and cover, and `id` — the meal's, or the one a new meal will have — so a cover picked offline
     * is queued against the meal it lands on (story 370).
     */
    set value(v: { name: string; date?: string; meal_type?: MealType; time?: string; notes?: string | null; image_path?: string | null; id?: string }) {
        const shadow = this.shadowRoot!;
        (shadow.querySelector('.name') as HTMLInputElement).value = v.name;
        if (v.notes !== undefined) (shadow.querySelector('.notes') as HTMLTextAreaElement).value = v.notes ?? '';
        if (v.image_path !== undefined || v.id !== undefined) {
            this.imagePath = v.image_path ?? null;
            (shadow.querySelector('photo-controls') as PhotoControls).show({ localRef: v.id ?? null, path: this.imagePath, alt: v.name, editable: true });
        }
        if (v.date !== undefined) (shadow.querySelector('.date') as HTMLInputElement).value = v.date;
        if (v.meal_type !== undefined) (shadow.querySelector('.slot') as HTMLSelectElement).value = v.meal_type;
        if (v.time !== undefined) (shadow.querySelector('.time') as HTMLInputElement).value = v.time;
    }

    /**
     * A picked food joins the list. One food is one line (418 #14) — story 434: picking it again
     * never changes that line unseen. Its sheet opens with the picked amount added and says so;
     * Done keeps it, Reset goes back, closing the sheet leaves the line as it was. While a sheet is
     * already open (a meal's ingredients arriving at once), the amount is added on the row itself.
     */
    addLine(line: LineView): void {
        const sameFood = (a: LineView) => 'food_item_id' in a.source && 'food_item_id' in line.source && a.source.food_item_id === line.source.food_item_id;
        const existing = this.linesValue.find(sameFood);
        if (!existing) {
            this.lines = [...this.linesValue, line];
            return;
        }
        const total = roundAmount(existing.amount + line.amount);
        if (this.sheet.open) {
            this.lines = this.linesValue.map((l) => (l === existing ? withAmount(l, total) : l));
            return;
        }
        this.openLine(existing.key, {
            amount: total,
            note: `Already here — adding ${formatMacro(line.amount)} ${unitLabel(line.unit)} makes ${formatMacro(total)} ${unitLabel(line.unit)}.`,
        });
    }

    private openKey: string | null = null;

    private get sheet(): HTMLDialogElement {
        return this.shadowRoot!.querySelector('.line-sheet') as HTMLDialogElement;
    }

    private openLine(key: string, proposal: { amount: number; note: string } | null = null): void {
        const line = this.linesValue.find((l) => l.key === key);
        if (!line) return;
        this.openKey = key;
        const sheet = this.sheet;
        (sheet.querySelector('.line-sheet-title') as HTMLElement).textContent = line.name;
        const note = sheet.querySelector('.line-sheet-note') as HTMLElement;
        note.textContent = proposal?.note ?? '';
        note.hidden = proposal === null;
        const detail = sheet.querySelector('line-editor') as LineEditor;
        detail.line = line;
        if (proposal) detail.propose(proposal.amount);
        showModalFresh(sheet);
    }

    /** The open line, changed (or removed with null) — the list and the editor hold the result. */
    private replaceOpen(change: (line: LineView) => LineView | null): void {
        const key = this.openKey;
        this.openKey = null;
        this.lines = this.linesValue.flatMap((l) => {
            if (l.key !== key) return [l];
            const next = change(l);
            return next ? [next] : [];
        });
    }

    attributeChangedCallback(): void { this.render(); }
    connectedCallback(): void { this.render(); }

    private get list(): LineList {
        return this.shadowRoot!.querySelector('line-list') as LineList;
    }

    private async save(): Promise<void> {
        const shadow = this.shadowRoot!;
        const error = shadow.querySelector('.error') as HTMLElement;
        const name = (shadow.querySelector('.name') as HTMLInputElement).value;
        const date = (shadow.querySelector('.date') as HTMLInputElement).value;
        const problems: string[] = [];
        if (this.linesValue.length === 0) problems.push('Add at least one food.');
        if (this.hasAttribute('name-required') && !name.trim()) problems.push('Give it a name.');
        if (this.mode !== 'meal' && !date) problems.push('Pick a day.');
        // An amount field left empty or 0 is not saved as some guess (story 368).
        if (!this.list.allAmountsValid()) problems.push('Every amount must be above 0.');
        if (problems.length > 0) {
            error.textContent = problems.join(' ');
            error.hidden = false;
            return;
        }
        error.hidden = true;
        return dispatchAndSettle(this, createLineSetSaveEvent({
            name,
            date,
            meal_type: (shadow.querySelector('.slot') as HTMLSelectElement).value as MealType,
            time: (shadow.querySelector('.time') as HTMLInputElement).value,
            lines: this.linesValue,
            also_update_meal: (shadow.querySelector('.also-meal-box') as HTMLInputElement).checked,
            notes: (shadow.querySelector('.notes') as HTMLTextAreaElement).value.trim() || null,
            image_path: this.imagePath,
        }));
    }

    private render(): void {
        const shadow = this.shadowRoot!;
        const mode = this.mode;
        (shadow.querySelector('.context') as HTMLElement).hidden = mode === 'meal';
        // Story 434: a meal scales too — Portion on every list of lines.
        this.list.toggleAttribute('scalable', true);
        this.namePlaceholder();
        this.list.setAttribute('add-label', mode === 'meal' ? 'Add ingredient' : 'Add food');
        (shadow.querySelector('.save') as HTMLElement).textContent = SAVE_LABELS[mode];
        (shadow.querySelector('.delete') as HTMLElement).hidden = !this.hasAttribute('deletable');
        // A log from a meal may update it (418 #8); a draft may also become one (423).
        const alsoMeal = shadow.querySelector('.also-meal') as HTMLElement;
        alsoMeal.hidden = !((mode === 'log' && this.hasAttribute('meal-linked')) || mode === 'draft');
        (shadow.querySelector('.also-meal-text') as HTMLElement).textContent = mode === 'draft' ? 'Also save as a meal' : 'Also update the meal';
        (shadow.querySelector('.cover') as HTMLElement).hidden = mode !== 'meal';
        (shadow.querySelector('.notes-field') as HTMLElement).hidden = mode !== 'meal';
        (shadow.querySelector('.name') as HTMLInputElement).required = this.hasAttribute('name-required');
    }
}

if (!customElements.get('line-set-editor')) {
    customElements.define('line-set-editor', LineSetEditor);
}
