import { HealthService } from '../services/health.service.js';
import type { LineView } from './line-view.js';

/**
 * Story 432 — a scanned code nothing knew, taught to the food picked for it in a "+ Add food"
 * sheet (342), now: the code means that food from the next scan on, whatever the editor below
 * does with the line. A product picked from Open Food Facts is not a food yet and has its own
 * code, so it binds nothing here; the add flow binds once it is logged (340).
 */
export async function bindPickedBarcode(line: LineView, bind: string | null | undefined): Promise<void> {
    if (!bind || !('food_item_id' in line.source)) return;
    await HealthService.mapFoodItemBarcode(line.source.food_item_id, bind);
}
